<script setup>import{ref}from'vue';defineProps({items:{type:Array,default:()=>[]},label:{type:String,default:'更多'}});const emit=defineEmits(['select']);const open=ref(false)</script><template><div class="drop"><button @click="open=!open">{{label}}⌄</button><div v-if="open" class="menu" role="menu"><button v-for="x in items" :key="x.value" role="menuitem" :disabled="x.disabled" @click="open=false;emit('select',x.value)">{{x.label}}</button></div></div></template><style scoped>.drop{position:relative;display:inline-flex}.drop>button,.menu button{padding:8px 12px;border:1px solid var(--line);background:var(--surface);color:var(--text);border-radius:7px}.menu{position:absolute;right:0;z-index:var(--z-dropdown);min-width:150px;padding:5px;background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow-lg)}.menu button{display:block;width:100%;text-align:left;border:0}</style>